import csv,io,json,hashlib,sys
from pathlib import Path
root=Path(__file__).resolve().parent;p=json.loads((root/'frozen-protocol.json').read_text());names=p['trainingFiles'] if sys.argv[1]=='training' else[p['heldFile']];runs=[]
for name in names:
 raw=(root/name).read_bytes();rows=list(csv.DictReader(io.StringIO(raw.decode('utf-8-sig'))));keys=list(rows[0]);time=next(k for k in keys if k.startswith('Time (s)'));angle=next(k for k in keys if k.startswith('Angle (rad)'));rate=next(k for k in keys if k.startswith('Angular Velocity (rad/s)'));selected=[(i,r)for i,r in enumerate(rows)if 5<=float(r[time])<=25];assert len(selected)==2001
 runs.append({'id':name[:-4],'kind':'measured','dynamics':'unforced_scalar_rotation','inertia':None,'initialRate':float(selected[0][1][rate]),'source':{'label':'Original PASCO author length3 0.426m, air only, independent repetition','recordingId':p['revision']+'/'+name,'url':'https://raw.githubusercontent.com/EnzeXu/Damped_Pendulum_Dataset/'+p['revision']+'/raw_data/'+name,'sha256':hashlib.sha256(raw).hexdigest(),'license':'Apache-2.0','selection':{'firstRow':selected[0][0],'lastRow':selected[-1][0],'rawCount':len(rows)},'transform':'Original5–25s timestamps and readings, no smoothing/resampling/recentering'},'rateObservation':{'unit':'rad/s','basis':'Original '+rate+' supplied PASCO column; relation to angle not established as independent','dependence':'not-assumed-independent'},'samples':[{'time':float(r[time]),'position':float(r[angle]),'rate':float(r[rate])}for _,r in selected]})
(root/(sys.argv[1]+'-runs.json')).write_text(json.dumps(runs,indent=2));print([(r['id'],len(r['samples']))for r in runs])
